import 'package:flutter/material.dart';
class AppTextField extends StatelessWidget { const AppTextField({super.key,required this.controller,required this.label,this.validator,this.maxLines=1,this.obscureText=false,this.keyboardType}); final TextEditingController controller; final String label; final String? Function(String?)? validator; final int maxLines; final bool obscureText; final TextInputType? keyboardType; @override Widget build(BuildContext context)=>TextFormField(controller:controller,validator:validator,maxLines:obscureText?1:maxLines,obscureText:obscureText,keyboardType:keyboardType,decoration:InputDecoration(labelText:label)); }